import{_ as p,V as o,W as c,X as n,Y as s,$ as t,Z as e,F as l}from"./framework-828e3e61.js";const i={},u=n("h1",{id:"可别再说不会ddd-六-聚合根与资源库",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#可别再说不会ddd-六-聚合根与资源库","aria-hidden":"true"},"#"),s(" 可别再说不会DDD（六）：聚合根与资源库")],-1),d=n("p",null,[s("注："),n("strong",null,"本文转载自码如云团队博文。")],-1),r={href:"https://docs.mryqr.com",target:"_blank",rel:"noopener noreferrer"},k=e(`<p>在上一篇请求处理流程中我们讲到，领域模型是DDD的核心，而聚合根又是领域模型的核心。从某种意义上讲，DDD中其它组件均可看作是对聚合根的支撑或辅助。</p><p>在本文中，我们将对聚合根以及与之密切相关的资源库(Repository)做详细的讲解。</p><h2 id="聚合根是什么" tabindex="-1"><a class="header-anchor" href="#聚合根是什么" aria-hidden="true">#</a> 聚合根是什么</h2><p>在DDD概念大白话一文中，我们讲到了“什么是聚合根”，这里再重复一下。聚合根中的“聚合”即“高内聚，低耦合”中的“内聚”之意；而“根”则是“根部”的意思，也即聚合根是一种统领式的存在。</p><p>事实上，并不存在一个教科书式的对聚合根的理论定义，你可以将聚合根理解为一个系统中最重要最显著的那些名词，这些名词是其所在的软件系统之所以存在的原因。为了给你一个直观的理解，以下是几个聚合根的例子：</p><ul><li>在一个电商系统中，一个订单（Order）对象表示一个聚合根</li><li>在一个CRM系统中，一个客户（Customer）对象表示一个聚合根</li><li>在一个银行系统中，一次交易（Transaction）对象表示一个聚合根</li></ul><p>你可能会问，软件中的概念已经很多了，为什么还要搞出个聚合根的概念？我们认为这里至少有2点原因：</p><ol><li>聚合根遵循了软件中“高内聚，低耦合”的基本原则。</li><li>聚合根体现了一种模块化的原则，模块化思想是被各个行业所证明的可以降低系统复杂度的一种思想。所谓的DDD是“软件核心复杂性应对之道”，也即这个意思，它将软件系统在人脑中所呈现地更加有序和简单，让人可以更好地理解和管控软件系统。</li></ol><p>在实际项目中识别聚合根时，我们需要对业务有深入的了解，因为只有这样你才知道到底哪些业务逻辑是内聚在一起的。这也是我们一直建议程序员和架构师们不要一味地埋头于技术而要多关注业务的原因。</p><p>事实上，如果让一个从来没有接触过DDD的人来建模，十有八九也能设计出上面的订单、客户和交易对象出来。没错，DDD绝非什么颠覆式的发明，依然只是在前人基础上的一种进步而已，这种进步更多的体现在一些设计原则上，对此我们将在下文进行详细阐述。</p><h2 id="聚合根基类" tabindex="-1"><a class="header-anchor" href="#聚合根基类" aria-hidden="true">#</a> 聚合根基类</h2><p>在代码实现层面，一般的实践是将所有的聚合根都继承自一个公共基类<code>AggregateRoot</code>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">//AggregateRoot</span>

<span class="token annotation punctuation">@Getter</span>
<span class="token keyword">public</span> <span class="token keyword">abstract</span> <span class="token keyword">class</span> <span class="token class-name">AggregateRoot</span> <span class="token keyword">implements</span> <span class="token class-name">Identified</span> <span class="token punctuation">{</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> id<span class="token punctuation">;</span><span class="token comment">//聚合根ID</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> tenantId<span class="token punctuation">;</span><span class="token comment">//租户ID</span>
    <span class="token keyword">private</span> <span class="token class-name">Instant</span> createdAt<span class="token punctuation">;</span><span class="token comment">//创建时间</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> createdBy<span class="token punctuation">;</span><span class="token comment">//创建人的MemberId</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> creator<span class="token punctuation">;</span><span class="token comment">//创建人姓名</span>
    <span class="token keyword">private</span> <span class="token class-name">Instant</span> updatedAt<span class="token punctuation">;</span><span class="token comment">//更新时间</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> updatedBy<span class="token punctuation">;</span><span class="token comment">//更新人MemberId</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> updater<span class="token punctuation">;</span><span class="token comment">//更新人姓名</span>
    <span class="token keyword">private</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">DomainEvent</span><span class="token punctuation">&gt;</span></span> events<span class="token punctuation">;</span><span class="token comment">//临时存放领域事件</span>
    <span class="token keyword">private</span> <span class="token class-name">LinkedList</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">OpsLog</span><span class="token punctuation">&gt;</span></span> opsLogs<span class="token punctuation">;</span><span class="token comment">//操作日志</span>

    <span class="token annotation punctuation">@Version</span>
    <span class="token annotation punctuation">@Getter</span><span class="token punctuation">(</span><span class="token constant">PRIVATE</span><span class="token punctuation">)</span>
    <span class="token keyword">private</span> <span class="token class-name">Long</span> _version<span class="token punctuation">;</span><span class="token comment">//版本号，实现乐观锁</span>

    <span class="token comment">//...此处省略了AggregateRoot中行为方法</span>

    <span class="token annotation punctuation">@Override</span>
    <span class="token keyword">public</span> <span class="token class-name">String</span> <span class="token function">getIdentifier</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> id<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在<code>AggregateRoot</code>中，包含聚合根ID（<code>id</code>）、创建信息(<code>createdAt</code>和<code>createdBy</code>)和更新信息（<code>updatedAt</code>和<code>updatedBy</code>）等数据。租户ID（<code>tenantId</code>）用于标定聚合根所在的租户（码如云是一个多租户系统）。另外，<code>events</code>用于临时性存放聚合根中所产生的领域事件，我们将在领域事件一文中对此所详细解释。</p><p>实际的聚合根继承自<code>AggregateRoot</code>，例如<strong>分组</strong>（Group）聚合根的实现如下：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Getter</span>
<span class="token annotation punctuation">@Document</span><span class="token punctuation">(</span><span class="token constant">GROUP_COLLECTION</span><span class="token punctuation">)</span>
<span class="token annotation punctuation">@TypeAlias</span><span class="token punctuation">(</span><span class="token constant">GROUP_COLLECTION</span><span class="token punctuation">)</span>
<span class="token annotation punctuation">@NoArgsConstructor</span><span class="token punctuation">(</span>access <span class="token operator">=</span> <span class="token constant">PRIVATE</span><span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">Group</span> <span class="token keyword">extends</span> <span class="token class-name">AggregateRoot</span> <span class="token punctuation">{</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> name<span class="token punctuation">;</span><span class="token comment">//名称</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> appId<span class="token punctuation">;</span><span class="token comment">//所在的app</span>
    <span class="token keyword">private</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">&gt;</span></span> managers<span class="token punctuation">;</span><span class="token comment">//管理员</span>
    <span class="token keyword">private</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">&gt;</span></span> members<span class="token punctuation">;</span><span class="token comment">//普通成员</span>
    <span class="token keyword">private</span> <span class="token keyword">boolean</span> archived<span class="token punctuation">;</span><span class="token comment">//是否归档</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> customId<span class="token punctuation">;</span><span class="token comment">//自定义编号</span>
    <span class="token keyword">private</span> <span class="token keyword">boolean</span> active<span class="token punctuation">;</span><span class="token comment">//是否启用</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> departmentId<span class="token punctuation">;</span><span class="token comment">//由哪个部门同步而来</span>
    
    <span class="token comment">//...此处省略了Group的行为方法</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="聚合根基本原则" tabindex="-1"><a class="header-anchor" href="#聚合根基本原则" aria-hidden="true">#</a> 聚合根基本原则</h2><p>从上面的代码例子可以看出，聚合根只是普通的Java对象而已，真正使之成为聚合根的是一些特定的设计原则。</p><h3 id="内聚性原则" tabindex="-1"><a class="header-anchor" href="#内聚性原则" aria-hidden="true">#</a> 内聚性原则</h3><p>这个原则不用我们再细讲了吧，估计你在大学里就学过，只举个例子，对于上面的分组<code>Group</code>对象来说，管理员<code>managers</code>、普通成员<code>members</code>以及启用标志<code>active</code>均是<code>Group</code>不可分割的属性，这些属性独立于<code>Group</code>是无法存在的。</p><h3 id="对外黑盒原则" tabindex="-1"><a class="header-anchor" href="#对外黑盒原则" aria-hidden="true">#</a> 对外黑盒原则</h3><p>对外黑盒原则讲的是，聚合根的外部（也即聚合根的调用方或客户方）不需要关心聚合根内部的实现细节，而只需要通过调用聚合根向外界暴露的共有业务方法即可。具体表现为，外部对聚合根的调用只能通过根对象完成，而不能调用聚合根内部对象上的方法。举个例子，在码如云中，管理员可以向<strong>分组</strong>(Group)中添加成员，具体的实现代码如下：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">//Group</span>

<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">addMembers</span><span class="token punctuation">(</span><span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">&gt;</span></span> memberIds<span class="token punctuation">,</span> <span class="token class-name">User</span> user<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">isSynced</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">MryException</span><span class="token punctuation">(</span><span class="token constant">GROUP_SYNCED</span><span class="token punctuation">,</span>
                <span class="token string">&quot;无法添加成员，已设置从部门同步。&quot;</span><span class="token punctuation">,</span>
                <span class="token string">&quot;groupId&quot;</span><span class="token punctuation">,</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">getId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">this</span><span class="token punctuation">.</span>members <span class="token operator">=</span> <span class="token function">concat</span><span class="token punctuation">(</span>members<span class="token punctuation">.</span><span class="token function">stream</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> memberIds<span class="token punctuation">.</span><span class="token function">stream</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">distinct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">collect</span><span class="token punctuation">(</span><span class="token function">toImmutableList</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    
    <span class="token function">addOpsLog</span><span class="token punctuation">(</span><span class="token string">&quot;设置成员&quot;</span><span class="token punctuation">,</span> user<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里，外部在向分组中添加成员时，需要调用<code>Group</code>上的<code>addMembers()</code>方法，该方法知道将<code>memberIds</code>添加到自身的<code>members</code>字段中，这个过程对外部是不可见的。与之相对的另一种方式是，外部调用法先拿到<code>Member</code>的<code>members</code>引用，然后由外部自行向<code>members</code>中添加<code>memberIds</code>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">//外部调用方</span>

<span class="token annotation punctuation">@Transactional</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">addGroupMembers</span><span class="token punctuation">(</span><span class="token class-name">String</span> groupId<span class="token punctuation">,</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">&gt;</span></span> memberIds<span class="token punctuation">,</span> <span class="token class-name">User</span> user<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">Group</span> group <span class="token operator">=</span> groupRepository<span class="token punctuation">.</span><span class="token function">byIdAndCheckTenantShip</span><span class="token punctuation">(</span>groupId<span class="token punctuation">,</span> user<span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span>group<span class="token punctuation">.</span><span class="token function">isSynced</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">MryException</span><span class="token punctuation">(</span><span class="token constant">GROUP_SYNCED</span><span class="token punctuation">,</span>
                <span class="token string">&quot;无法添加成员，已设置从部门同步。&quot;</span><span class="token punctuation">,</span>
                <span class="token string">&quot;groupId&quot;</span><span class="token punctuation">,</span> group<span class="token punctuation">.</span><span class="token function">getId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">&gt;</span></span> members <span class="token operator">=</span> group<span class="token punctuation">.</span><span class="token function">getMembers</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    members<span class="token punctuation">.</span><span class="token function">addAll</span><span class="token punctuation">(</span>memberIds<span class="token punctuation">)</span><span class="token punctuation">;</span>
    groupRepository<span class="token punctuation">.</span><span class="token function">save</span><span class="token punctuation">(</span>group<span class="token punctuation">)</span><span class="token punctuation">;</span>

    log<span class="token punctuation">.</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string">&quot;Added members{} to group[{}].&quot;</span><span class="token punctuation">,</span> memberIds<span class="token punctuation">,</span> groupId<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这种方式是一种反模式，存在以下缺点：</p><ul><li>外部需要了解<code>Group</code>的内部结构，背离了对外黑盒原则，本例中，外部通过<code>group.getMembers()</code>获取到了<code>Group</code>内部的<code>members</code>属性</li><li>聚合根内部的业务逻辑泄漏到了外部，背离了内聚性原则，本例中，对<code>group.isSynced()</code>的调用原本应该放在<code>Group</code>中的，结果却由外部承担了该职责</li></ul><p>在对外黑盒原则的指导下，聚合根自然形成了一个边界，它站在这个边界上向外声明：“我所包围着的内部的所有均由我负责，如果谁想访问我的内部，直接访问是被禁止的，只能通过我这个“根”来访问。”</p><h3 id="不变条件原则" tabindex="-1"><a class="header-anchor" href="#不变条件原则" aria-hidden="true">#</a> 不变条件原则</h3><p>不变条件(Invariants)表示聚合根需要保证其内部在任何时候均处于一种合法的状态（也即数据一致性需要得到保证），一个常见的例子是订单(Order)中有订单项(OrderItem)和订单价格(Price)，当订单项发生变化时，其价格应该随之发生变化，并且这两种变化应该在订单的同一个业务方法中完成。这一点是好理解的，既然聚合根对外是一个黑盒，那么外界便不会负责给你聚合根擦屁股，你聚合根自己需要保证自身的正确性。</p><p>在码如云中，应用管理员可以向<strong>分组</strong>(Group)中添加分组管理员。这其中有层隐含意思是，既然分组管理员也是分组成员，那么在添加分组管理员的同时需要一并将其添加到分组成员中，具体实现代码如下：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">//Group</span>

<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">addManager</span><span class="token punctuation">(</span><span class="token class-name">String</span> memberId<span class="token punctuation">,</span> <span class="token class-name">User</span> user<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token keyword">this</span><span class="token punctuation">.</span>members<span class="token punctuation">.</span><span class="token function">contains</span><span class="token punctuation">(</span>memberId<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">this</span><span class="token punctuation">.</span>members <span class="token operator">=</span> <span class="token function">concat</span><span class="token punctuation">(</span>members<span class="token punctuation">.</span><span class="token function">stream</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">Stream</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span>memberId<span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">distinct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">collect</span><span class="token punctuation">(</span><span class="token function">toImmutableList</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">this</span><span class="token punctuation">.</span>managers <span class="token operator">=</span> <span class="token function">concat</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>managers<span class="token punctuation">.</span><span class="token function">stream</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">Stream</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span>memberId<span class="token punctuation">)</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">distinct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">collect</span><span class="token punctuation">(</span><span class="token function">toImmutableList</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    
    <span class="token function">raiseEvent</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">GroupManagersChangedEvent</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">getId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">getAppId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> user<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    
    <span class="token function">addOpsLog</span><span class="token punctuation">(</span><span class="token string">&quot;添加管理员&quot;</span><span class="token punctuation">,</span> user<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在本例的添加分组管理员<code>addManager()</code>方法中，我们除了向<code>managers</code>中添加成员外，还保证了该成员也出现在<code>members</code>中。这里的“分组管理员也是分组成员”即是一种不变条件，我们需要在聚合根内部保证不变条件不被破坏，因为不变条件往往意味着核心的业务逻辑。</p><h3 id="通过id引用其他聚合根原则" tabindex="-1"><a class="header-anchor" href="#通过id引用其他聚合根原则" aria-hidden="true">#</a> 通过ID引用其他聚合根原则</h3><p>当一个聚合根需要引用另一个聚合根时，并不需要维持对另一聚合根的整体引用，而是只需通过ID进行引用即可。这个原则的出发点是：聚合根和聚合根之间是一种平级关系，并不是隶属关系，每个聚合根本身是一个相对独立的模块，其与其他聚合根的关系应该通过ID这种松耦合的方式进行引用，如果整体引用则更像是一种包含关系。</p><p>在码如云中，<strong>分组</strong>(Group)通过<code>appId</code>引用其所属的<strong>应用</strong>(App)，通过<code>departmentId</code>引用所同步的<strong>部门</strong>(Department)，而在<code>managers</code>和<code>members</code>字段中，则是以<code>memberId</code>引用相应<strong>成员</strong>(Member)：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Getter</span>
<span class="token annotation punctuation">@Document</span><span class="token punctuation">(</span><span class="token constant">GROUP_COLLECTION</span><span class="token punctuation">)</span>
<span class="token annotation punctuation">@TypeAlias</span><span class="token punctuation">(</span><span class="token constant">GROUP_COLLECTION</span><span class="token punctuation">)</span>
<span class="token annotation punctuation">@NoArgsConstructor</span><span class="token punctuation">(</span>access <span class="token operator">=</span> <span class="token constant">PRIVATE</span><span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">Group</span> <span class="token keyword">extends</span> <span class="token class-name">AggregateRoot</span> <span class="token punctuation">{</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> name<span class="token punctuation">;</span><span class="token comment">//名称</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> appId<span class="token punctuation">;</span><span class="token comment">//所在的app</span>
    <span class="token keyword">private</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">&gt;</span></span> managers<span class="token punctuation">;</span><span class="token comment">//管理员</span>
    <span class="token keyword">private</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">&gt;</span></span> members<span class="token punctuation">;</span><span class="token comment">//普通成员</span>
    <span class="token keyword">private</span> <span class="token keyword">boolean</span> archived<span class="token punctuation">;</span><span class="token comment">//是否归档</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> customId<span class="token punctuation">;</span><span class="token comment">//自定义编号</span>
    <span class="token keyword">private</span> <span class="token keyword">boolean</span> active<span class="token punctuation">;</span><span class="token comment">//是否启用</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> departmentId<span class="token punctuation">;</span><span class="token comment">//由哪个部门同步而来</span>
   
    <span class="token comment">//...省略其他代码</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="与基础设施无关原则" tabindex="-1"><a class="header-anchor" href="#与基础设施无关原则" aria-hidden="true">#</a> 与基础设施无关原则</h3><p>既然整个领域模型与基础设施无关，那么位于领域模型之内的聚合根自然也不能与基础设施相关，这样好处是将业务复杂度与技术复杂度解耦开来，让业务模型可以独立于技术设施而完成自身的演变。比如，假设一个项目需要从Spring框架迁移到Guice框架，此时如果能够保证领域模型与基础设施的无关性，那么对领域模型的迁移过程讲变得非常简单，基本上无需修改任何代码直接拷贝到新的项目中即可。</p>`,39),m=n("code",null,"AggregateRoot",-1),v=n("code",null,"Group",-1),b=n("code",null,"@Version",-1),g=n("code",null,"@Document",-1),h=n("code",null,"@TypeAlias",-1),y={href:"https://khorikov.org/posts/2020-04-20-when-do-you-need-persistence-model/",target:"_blank",rel:"noopener noreferrer"},f={href:"https://stackoverflow.com/questions/14024912/ddd-persistence-model-and-domain-model",target:"_blank",rel:"noopener noreferrer"},I=n("h2",{id:"跨聚合根用例",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#跨聚合根用例","aria-hidden":"true"},"#"),s(" 跨聚合根用例")],-1),w=n("p",null,"通常来讲，一个业务用例只会操作一个（或一种）聚合根。但有时，一个业务用例可能会导致多个（或多种）聚合根对象的更新，此时可分两种情况：",-1),_={href:"https://aws.amazon.com/event-driven-architecture/",target:"_blank",rel:"noopener noreferrer"},D=n("li",null,"如果聚合根位于同一个进程空间，此时依然可以选择事件驱动架构，但是另一种更简单实用的方式是直接同时更新多个聚合根，毕竟此时对所有聚合根的更新均处于同一个本地事务中。",-1),S={href:"https://www.mryqr.com/",target:"_blank",rel:"noopener noreferrer"},G=n("strong",null,"实例",-1),R=n("strong",null,"码牌",-1),A=e(`<div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">//QrCommandService</span>
    
<span class="token annotation punctuation">@Transactional</span>
<span class="token keyword">public</span> <span class="token class-name">CreateQrResponse</span> <span class="token function">createQr</span><span class="token punctuation">(</span><span class="token class-name">CreateQrCommand</span> command<span class="token punctuation">,</span> <span class="token class-name">User</span> user<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">String</span> name <span class="token operator">=</span> command<span class="token punctuation">.</span><span class="token function">getName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">String</span> groupId <span class="token operator">=</span> command<span class="token punctuation">.</span><span class="token function">getGroupId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name">Group</span> group <span class="token operator">=</span> groupRepository<span class="token punctuation">.</span><span class="token function">cachedByIdAndCheckTenantShip</span><span class="token punctuation">(</span>groupId<span class="token punctuation">,</span> user<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">String</span> appId <span class="token operator">=</span> group<span class="token punctuation">.</span><span class="token function">getAppId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">App</span> app <span class="token operator">=</span> appRepository<span class="token punctuation">.</span><span class="token function">cachedById</span><span class="token punctuation">(</span>appId<span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name">PlatedQr</span> platedQr <span class="token operator">=</span> qrFactory<span class="token punctuation">.</span><span class="token function">createPlatedQr</span><span class="token punctuation">(</span>name<span class="token punctuation">,</span> group<span class="token punctuation">,</span> app<span class="token punctuation">,</span> user<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">QR</span> qr <span class="token operator">=</span> platedQr<span class="token punctuation">.</span><span class="token function">getQr</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">Plate</span> plate <span class="token operator">=</span> platedQr<span class="token punctuation">.</span><span class="token function">getPlate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">//同时保存QR和Plate</span>
    qrRepository<span class="token punctuation">.</span><span class="token function">save</span><span class="token punctuation">(</span>qr<span class="token punctuation">)</span><span class="token punctuation">;</span>
    plateRepository<span class="token punctuation">.</span><span class="token function">save</span><span class="token punctuation">(</span>plate<span class="token punctuation">)</span><span class="token punctuation">;</span>

    log<span class="token punctuation">.</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string">&quot;Created qr[{}] of group[{}] of app[{}].&quot;</span><span class="token punctuation">,</span>
            qr<span class="token punctuation">.</span><span class="token function">getId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> groupId<span class="token punctuation">,</span> appId<span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token class-name">CreateQrResponse</span><span class="token punctuation">.</span><span class="token function">builder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">qrId</span><span class="token punctuation">(</span>qr<span class="token punctuation">.</span><span class="token function">getId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">plateId</span><span class="token punctuation">(</span>plate<span class="token punctuation">.</span><span class="token function">getId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">groupId</span><span class="token punctuation">(</span>groupId<span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">appId</span><span class="token punctuation">(</span>appId<span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>可以看到，在用例方法<code>createQr()</code>中，我们先后调用<code>qrRepository.save(qr)</code>和<code>plateRepository.save(plate)</code>分别完成了对<code>QR</code>和<code>Plate</code>的持久化。</p><p>如果你希望了解事件驱动架构相关的知识，请参考本系列的领域事件一文。</p><h2 id="资源库" tabindex="-1"><a class="header-anchor" href="#资源库" aria-hidden="true">#</a> 资源库</h2>`,4),j=n("strong",null,"资源库",-1),x={href:"https://www.baeldung.com/java-dao-pattern",target:"_blank",rel:"noopener noreferrer"},q=n("strong",null,"成员",-1),C=e(`<div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">interface</span> <span class="token class-name">MemberRepository</span> <span class="token punctuation">{</span>
    <span class="token class-name">Member</span> <span class="token function">byId</span><span class="token punctuation">(</span><span class="token class-name">String</span> id<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">//返回聚合根</span>

    <span class="token class-name">Optional</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Member</span><span class="token punctuation">&gt;</span></span> <span class="token function">byIdOptional</span><span class="token punctuation">(</span><span class="token class-name">String</span> id<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">//返回聚合根</span>

    <span class="token class-name">Member</span> <span class="token function">byIdAndCheckTenantShip</span><span class="token punctuation">(</span><span class="token class-name">String</span> id<span class="token punctuation">,</span> <span class="token class-name">User</span> user<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">//返回聚合根</span>

    <span class="token keyword">void</span> <span class="token function">save</span><span class="token punctuation">(</span><span class="token class-name">Member</span> member<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">//聚合根作为参数</span>

    <span class="token keyword">void</span> <span class="token function">delete</span><span class="token punctuation">(</span><span class="token class-name">Member</span> member<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">//聚合根作为参数</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>行业中这么一个现象，很多程序员在面对一个新的业务需求时，首先想到的是如何设计数据库的表结构，然后再编写业务代码。在DDD中，这是一种反模式，既然是“领域驱动”，那么我们首先应该关心的是如何业务建模，而不是数据库建模。事实上，正如Robert C. Martin在《整洁架构》一书中所说，数据库只是一个实现细节而已，不应该成为软件建模的主体。</p><p>资源库的作用，在于它在业务复杂度和技术复杂度之间做了一层很好的隔离，让我们可以独立地看待软件的业务模型而不受技术设施的影响。从本质上讲，资源库做的事情只是实现数据在内存和磁盘之间相互传输而已。在编程实现业务逻辑的时候，我们只需关心内存中的那个聚合根对象即可，当聚合根对象的状态由于业务操作发生了改变之后，再调用资源库将新的聚合根状态同步到磁盘中完成持久化，在调用时我们假设并相信资源库一定可以完成其自身的使命。</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Transactional</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">addGroupManager</span><span class="token punctuation">(</span><span class="token class-name">String</span> groupId<span class="token punctuation">,</span> <span class="token class-name">String</span> memberId<span class="token punctuation">,</span> <span class="token class-name">User</span> user<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">Group</span> group <span class="token operator">=</span> groupRepository<span class="token punctuation">.</span><span class="token function">byIdAndCheckTenantShip</span><span class="token punctuation">(</span>groupId<span class="token punctuation">,</span> user<span class="token punctuation">)</span><span class="token punctuation">;</span>

    group<span class="token punctuation">.</span><span class="token function">addManager</span><span class="token punctuation">(</span>memberId<span class="token punctuation">,</span> user<span class="token punctuation">)</span><span class="token punctuation">;</span>
    
    groupRepository<span class="token punctuation">.</span><span class="token function">save</span><span class="token punctuation">(</span>group<span class="token punctuation">)</span><span class="token punctuation">;</span>
    
    log<span class="token punctuation">.</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string">&quot;Added manager[{}] to group[{}].&quot;</span><span class="token punctuation">,</span> memberId<span class="token punctuation">,</span> groupId<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在上例的“向分组中添加管理员”用例中，首先通过资源库<code>GroupRepository</code>的<code>byIdAndCheckTenantShip()</code>方法得到聚合根<code>Group</code>对象，然后再完成后续操作。这里的<code>addGroupManager()</code>无需知道<code>Group</code>是如何加载的，甚至不用知道后台使用的是MySQL还是MongoDB或是其他，反正通过调用<code>GroupRepository.byIdAndCheckTenantShip()</code>可以得到一个完整合法的<code>Group</code>对象即可。</p><p>在资源库中，最重要的方法有以下3个：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">interface</span> <span class="token class-name">GroupRepository</span> <span class="token punctuation">{</span>
    
    <span class="token class-name">Group</span> <span class="token function">byId</span><span class="token punctuation">(</span><span class="token class-name">String</span> id<span class="token punctuation">)</span><span class="token punctuation">;</span>
    
    <span class="token keyword">void</span> <span class="token function">save</span><span class="token punctuation">(</span><span class="token class-name">Group</span> group<span class="token punctuation">)</span><span class="token punctuation">;</span>
    
    <span class="token keyword">void</span> <span class="token function">delete</span><span class="token punctuation">(</span><span class="token class-name">Group</span> group<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其中，<code>byId()</code>用于根据ID获取指定聚合根，<code>save()</code>用于保存聚合根，<code>delete()</code>则用于删除聚合根。除此之外，资源库中还可以包含更多的查询方法，比如在<code>GroupRepository</code>中还包含以下方法：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">//根据部门ID查找分组</span>
<span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Group</span><span class="token punctuation">&gt;</span></span> <span class="token function">byDepartmentId</span><span class="token punctuation">(</span><span class="token class-name">String</span> departmentId<span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">//根据ID查找分组，返回Optional</span>
<span class="token class-name">Optional</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Group</span><span class="token punctuation">&gt;</span></span> <span class="token function">byIdOptional</span><span class="token punctuation">(</span><span class="token class-name">String</span> id<span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">//根据ID查找分组，同时检查租户</span>
<span class="token class-name">Group</span> <span class="token function">byIdAndCheckTenantShip</span><span class="token punctuation">(</span><span class="token class-name">String</span> id<span class="token punctuation">,</span> <span class="token class-name">User</span> user<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>需要注意的是，这里的查询方法指的是在实现业务逻辑的过程中需要做的查询操作，并不是为了前端显示那种纯粹的查询，因为纯粹的查询操作不见得一定要放到资源库中，而是可以作为一个单独的关注点通过CQRS解决。</p><p>在DDD项目中，通常将资源库分为接口类和实现类，将接口类放置在领域模型<code>domain</code>包中，而将实现类放置在基础设施<code>infrastructure</code>包中，这种做法有2点好处：</p><ol><li>通过依赖反转，使得领域模型不依赖于基础设施</li><li>实现资源库的可插拔性，比如未来需要从MongoDB迁移到MySQL，那么只需创建新的实现类即可</li></ol><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结" aria-hidden="true">#</a> 总结</h2><p>在本文中，我们讲到了作为DDD核心的聚合根的设计原则及实现，其中包含内聚原则、对外黑盒原则和不变条件原则等。此外，我们也对与聚合根密切相关的资源库做了讲解。在下一篇实体与值对象中，我们将讲到实体和值对象之间的区别，以及各自的典型编码实践。</p>`,14);function L(M,O){const a=l("ExternalLinkIcon");return o(),c("div",null,[u,d,n("p",null,[s("原文链接："),n("a",r,[s("https://docs.mryqr.com"),t(a)])]),k,n("p",null,[s("事实上，码如云尚未完全做到这一点，从上面的例子中可以看到，"),m,s("和"),v,s("对Spring框架中的"),b,s("、"),g,s("和"),h,s("3个与持久化相关的注解存在引用。如需解决这个问题，可以考虑在领域模型之外另建专门用于数据库访问的"),n("a",y,[s("持久化对象(Persistence Model)"),t(a)]),s("。但是，引入持久化对象是有成本的，比如需要维护领域对象与持久化对象之间的相互转化等。在码如云，我们选择了妥协，一方面考虑到持久化对象的成本，另一方面我们也预见在将来要迁移出Spring框架的几率是非常小的。不过，除了前面提到的3个注解之外，码如云中的聚合根可以做到对基础设施没有任何其他引用。关于持久化对象，在"),n("a",f,[s("Stackoverflow"),t(a)]),s("上有过非常有意义的讨论，读者可自行阅览。")]),I,w,n("ol",null,[n("li",null,[s("如果聚合根位于不同的进程空间（比如不同的微服务）中，那么解决方式一是可以使用"),n("a",_,[s("事件驱动架构(EDA)"),t(a)]),s("，二是通过全局事务（比如JTA）完成。基于全局事务的性能和效率低下等问题，DDD社区一般建议采用事件驱动架构，即在一个进程空间中只对其包含的聚合根进行操作，然后通过向其他进程空间发送事件通知的方式，使得其他进程空间做相应的聚合根更新。")]),D]),n("p",null,[n("a",S,[s("码如云"),t(a)]),s("是一个单体系统，因此属于以上的第2种情况，我们根据聚合根之间的业务紧密程度的不同，在有些场景下选择了同时更新多个聚合根，在另一些场景下则选择通过事件驱动机制解决。比如，在“创建实例”的用例中，除了创建"),G,s("(QR)之外，还需要创建该实例对应的"),R,s("(Plate)，由于“有实例就必有码牌”，因此它们之间是紧密联系的，故在码如云中我们选择了在同一个本地事务中同时更新实例和码牌：")]),A,n("p",null,[s("在DDD中，"),j,s("(Repository)以聚合根为单位完成对数据库的访问。这里的重点是“以聚合根为单位”，也即只有聚合根才配得上拥有资源库（毕竟在DDD中大家都是围绕着聚合根转的嘛），其他对象（比如非聚合根实体）是没有对应资源库的，这也是资源库和"),n("a",x,[s("DAO"),t(a)]),s("最大的区别。在编码实现时，资源库方法所接受的参数和返回的数据都应该是聚合根对象，例如，在码如云中，"),q,s("(Member)聚合根对应的资源库定义如下：")]),C])}const Q=p(i,[["render",L],["__file","ddd-aggregate-root-and-repository.html.vue"]]);export{Q as default};
